head.script:
scwin.gVar = {
    "cReadOnly" : "",
    "cReadOnlyClass" : "",
    "cDisabled" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[secret > P > readOnly]<br/>Secret 컴포넌트의 읽기 전용(readonly) 상태를 설정합니다.",
    "validation" : [
        "true 설정 시, 컴포넌트를 읽기 전용(readonly) 상태로 설정합니다.",
        "true 설정 시, readOnlyClass 속성값이 CSS 클래스로 적용됩니다.",
        "false 설정 시, 컴포넌트의 읽기 전용(readonly) 상태를 해제합니다.",
        "미설정 시, 컴포넌트의 읽기 전용(readonly) 상태를 해제합니다.",
        "읽기 전용(readonly) 상태일때 사용자는 컴포넌트의 값을 직접 입력하거나 편집할 수 없습니다.",
        "읽기 전용(readonly) 상태일때 disabled 속성과 달리 컴포넌트는 포커스를 받을 수 있고, 마우스/키보드 관련 이벤트도 발생합니다.",
        "단, 컴포넌트가 실제로 포커스를 얻거나 잃어도 onfocus, onblur 이벤트는 발생하지 않습니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 정적 select1 기본값 설정 (gdl_boolean 은 코드값 1=미설정 / 2=true / 3=false)
    con_readOnly.setValue("2");
    con_readOnlyClass.setSelectedIndex(0);
    con_disabled.setValue("1");

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 컴포넌트 있으면 삭제
    if (typeof label1 !== 'undefined') {
        label1.remove();
    }

    if (typeof input_prev !== 'undefined') {
        input_prev.remove();
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="[전제] target1 은 Secret 컴포넌트(초기값 secret), 위 input_prev 는 Tab 이동 출발점입니다\n[절차] 위 조건 선택 -> Target 재생성 -> 검증 목적에 따라 아래 중 하나를 수행\n - 입력/편집 차단 : target1 에 직접 타이핑 -> 값 확인 클릭\n - 포커스와 이벤트 : target1 클릭 또는 input_prev 에서 Tab 키로 이동 -> target1 에서 키 입력\n - disabled 대비 : disabled 를 true 로 재생성 후 같은 조작 반복\n[확인] 재생성 시 출력되는 class 문자열과 readonly / disabled 속성값, 결과창의 이벤트 발생 줄과 포커스 요소, 값 확인의 값 길이로 판정"', '', 'label1');

    // Tab 이동 출발점
    await $c.gcm.createBasicInput('', '', 'input_prev');

    // 조건 설정
    scwin.gVar["cReadOnly"] = con_readOnly.getText();
    scwin.gVar["cReadOnlyClass"] = con_readOnlyClass.getValue();
    scwin.gVar["cDisabled"] = con_disabled.getText();

    let properties = {
        readOnly : scwin.gVar["cReadOnly"],
        readOnlyClass : scwin.gVar["cReadOnlyClass"],
        disabled : scwin.gVar["cDisabled"],
    }

    let cList = $c.gcm.createCList(properties);

    let eList = $c.gcm.createEList(["onclick", "onkeydown", "onfocus", "onblur"]);

    // comp 생성 함수 호출 (헬퍼가 생성 직후 setValue 로 초기값 secret 설정)
    await $c.gcm.createBasicSecret(cList, eList);

    scwin.printCompState();
}



// 미설정 표기 변환
scwin.fn_disp = function (strValue) {
    return (strValue === "") ? "미설정" : strValue;
}



// 현재 포커스를 가진 컴포넌트 (onfocus 가 발생하지 않아도 포커스 여부를 확인하기 위한 수단)
scwin.fn_active = function () {
    let objActive = document.activeElement;

    if (objActive === target1.render)
        return "target1";

    if (objActive === input_prev.render)
        return "input_prev";

    return "그 외";
}



// 재생성 시 적용 상태 출력 - validation 1, 2, 3, 4 판정 출력
scwin.printCompState = function () {
    let objInput = target1.render;

    wf_body_bottom.getObj("scwin").setReturnValue("readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + " / readOnlyClass " + scwin.fn_disp(scwin.gVar["cReadOnlyClass"]) + " / disabled " + scwin.fn_disp(scwin.gVar["cDisabled"]) + " -> class : " + objInput.className + " / readonly 속성 : " + objInput.hasAttribute("readonly") + " / disabled 속성 : " + objInput.hasAttribute("disabled"));
}



// 타이핑 후 입력값 확인 - validation 5 판정 출력
scwin.btn_getValue_onclick = function (e) {
    let strValue = target1.getValue() || "";

    wf_body_bottom.getObj("scwin").setReturnValue("readOnly " + scwin.fn_disp(scwin.gVar["cReadOnly"]) + " -> target1 값 : " + strValue + " (" + strValue.length + "자)");
}



// validation 6 판정 출력 (핸들러별 즉시 1줄 출력)
scwin.target1_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onclick 이벤트 발생 -> 포커스 요소 : " + scwin.fn_active());
}



// validation 6 판정 출력 (핸들러별 즉시 1줄 출력)
scwin.target1_onkeydown = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onkeydown 이벤트 발생 -> 포커스 요소 : " + scwin.fn_active());
}



// validation 7 판정 출력 (읽기 전용 상태에서는 이 줄이 출력되지 않아야 함)
scwin.target1_onfocus = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onfocus 이벤트 발생");
}



// validation 7 판정 출력 (읽기 전용 상태에서는 이 줄이 출력되지 않아야 함)
scwin.target1_onblur = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("target1_onblur 이벤트 발생");
}
